% BP detection for scat coef and backscat

names_sc={'BsB0_S', 'BsG0_S', 'BsR0_S'};
break_ZEP_scat_BP=change_point_analysis_Def(ZEP_rd,names_sc,0.05,'ZEP','scattering');
T_ZEP_scat_BP=make_table_breakpoints_def(break_ZEP_scat_BP);

names_bsc={'BbsB0_S', 'BbsG0_S', 'BbsR0_S'};
break_ZEP_bscat_BP=change_point_analysis_Def(ZEP_rd,names_bsc,0.05,'ZEP','Backscattering');
T_ZEP_bscat_BP=make_table_breakpoints_def(break_ZEP_bscat_BP);
%%
% BP detection for abs
names_abs={'BaR0_A'};
break_ZEP_abs_BP=change_point_analysis_Def(ZEP_rd,names_abs,0.05,'ZEP','Absorption');
T_ZEP_abs_BP=make_table_breakpoints_def(break_ZEP_abs_BP);
%%
lambdaSC=[450;550;700];
lambdaAE=637;
% % lambdaAE7=[370 470 520 590 660 880 950];
ZEP_cal=compute_exp_SSA(ZEP_rd,lambdaSC, lambdaAE);
plotFigControl_cal(ZEP_cal, ZEP_st.name);
%%
% BP detection for expS, Backscat fraction, expA and SSA

names_exps={'expS_bg0', 'expS_br0', 'expS_gr0'};
break_ZEP_exps_BP=change_point_analysis_Def(ZEP_cal,names_exps,0.05,'ZEP','scattering exp');
T_ZEP_exps_BP=make_table_breakpoints_def(break_ZEP_exps_BP);

names_BbF={'BbsFG'};
break_ZEP_BbF_BP=change_point_analysis_Def(ZEP_cal,names_BbF,0.05,'ZEP','backscat fraction');
T_ZEP_BbF_BP=make_table_breakpoints_def(break_ZEP_BbF_BP);

names_SSA={'SSA011'};
break_ZEP_SSA_BP=change_point_analysis_Def(ZEP_cal,names_SSA,0.05,'ZEP','SSA');
T_ZEP_SSA_BP=make_table_breakpoints_def(break_ZEP_SSA_BP);
